 $input=json_decode(file_get_contents('php://input'),true,32,JSON_THROW_ON_ERROR);$seed=require __DIR__.'/../_core/GallerySeed.php';$convert=static function(array $p):array{$id=(int)($p['id']??-1);$image=(int)($p['image']??-1);return ['id'=>$id,'slug'=>preg_replace('/[^a-z0-9-]/','',basename(trim($p['slug']??'new-preview','/')))?:'new-preview','title'=>mb_substr($p['title']??'Новый товар',0,190),'category'=>mb_substr($p['category']??'Коллекция',0,120),'collection'=>'Из вашей демо-сессии','brand'=>mb_substr($p['brand']??'Gallery',0,120),'description'=>Content::html($p['body']??''),'specs'=>mb_substr(implode("\n",array_map(fn($v)=>($v['name']??'').': '.($v['value']??''),array_slice((array)($p['specifications']??[]),0,30))),0,5000),'images'=>$image>=0&&$image<6?['/themes/gallery/assets/object-'.$image.'.webp']:[],'variants'=>!empty($p['variants'])?array_map(fn($v)=>['id'=>abs($id)*100+(int)($v['id']??1),'sku'=>mb_substr($v['sku']??'DEMO-'.abs($id),0,100),'title'=>mb_substr($v['name']??'Основной',0,190),'price'=>max(100,(int)round((float)($v['price']??$p['price']??0)*100)),'stock'=>max(0,(int)($v['stock']??0)),'active'=>1],array_slice($p['variants'],0,50)):[['id'=>$id,'sku'=>$p['sku']??'DEMO-'.abs($id),'title'=>'Основной','price'=>max(100,(int)round((float)($p['price']??0)*100)),'stock'=>max(0,(int)($p['stock']??0)),'active'=>1]]];};
